score = 87

if score >= 90:
    print("Grade: A")
    print("Excellent!")
elif score >= 80:
    print("Grade: B")
    print("Great job!")
elif score >= 70:
    print("Grade: C")
    print("Not bad!")
elif score >= 60:
    print("Grade: D")
    print("Needs work.")
else:
    print("Grade: F")
    print("Try harder!")
